import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.payments.api.PaymentsFacade;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class ShopFlowTest {

    @Test
    void anOrderCanBePlacedPaidAndCancelled() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            PaymentsFacade payments = shop.getBean(PaymentsFacade.class);

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            payments.charge(id, Money.pln(1000));
            orders.cancel(id);

            assertEquals("CANCELLED", orders.summary(id).status());
            assertEquals("CAPTURED", payments.status(id));
        }
    }
}

package com.wolinski.shop.platform;

import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.AbstractPlatformTransactionManager;
import org.springframework.transaction.support.DefaultTransactionStatus;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/** The repositories keep their data in memory, so a transaction only has to exist, with its synchronizations. */
public class InMemoryTransactionManager extends AbstractPlatformTransactionManager {

    private static final ThreadLocal<Boolean> OPEN = ThreadLocal.withInitial(() -> false);

    private record Tx(boolean existing) {
    }

    /**
     * True from begin until commit or rollback. Spring's isActualTransactionActive() stays true during
     * after-commit callbacks as well, when the work has already been committed.
     */
    public static boolean isOpen() {
        return OPEN.get();
    }

    @Override
    protected Object doGetTransaction() {
        return new Tx(TransactionSynchronizationManager.isActualTransactionActive() && OPEN.get());
    }

    @Override
    protected boolean isExistingTransaction(Object transaction) {
        return ((Tx) transaction).existing();
    }

    @Override
    protected void doBegin(Object transaction, TransactionDefinition definition) {
        OPEN.set(true);
    }

    @Override
    protected Object doSuspend(Object transaction) {
        OPEN.set(false);
        return transaction;
    }

    @Override
    protected void doResume(Object transaction, Object suspendedResources) {
        OPEN.set(true);
    }

    @Override
    protected void doCommit(DefaultTransactionStatus status) {
        OPEN.set(false);
    }

    @Override
    protected void doRollback(DefaultTransactionStatus status) {
        OPEN.set(false);
    }
}

package com.wolinski.shop;

import com.wolinski.shop.platform.InMemoryTransactionManager;
import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;

@Configuration
@ComponentScan
@EnableTransactionManagement
public class ShopConfig {

    @Bean
    Clock clock() {
        return Clock.systemUTC();
    }

    @Bean
    PlatformTransactionManager transactionManager() {
        return new InMemoryTransactionManager();
    }
}

package com.wolinski.shop.payments.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.api.PaymentRefunded;
import com.wolinski.shop.payments.api.PaymentsFacade;
import java.time.Clock;
import java.util.List;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PaymentService implements PaymentsFacade {

    private final PaymentRepository payments;
    private final Clock clock;
    private final ApplicationEventPublisher events;

    public PaymentService(PaymentRepository payments, Clock clock, ApplicationEventPublisher events) {
        this.payments = payments;
        this.clock = clock;
        this.events = events;
    }

    @Override
    @Transactional
    public void charge(String orderId, Money amount) {
        payments.save(new Payment(orderId, amount, clock.instant()));
    }

    @Override
    @Transactional
    public void refund(String orderId, Money amount) {
        List<Payment> found = payments.findByOrderId(orderId);
        found.getLast().addRefund(amount);
        events.publishEvent(new PaymentRefunded(orderId, amount));
    }

    @Override
    @Transactional(readOnly = true)
    public List<Payment> paymentsOf(String orderId) {
        return payments.findByOrderId(orderId);
    }

    @Override
    @Transactional(readOnly = true)
    public String status(String orderId) {
        return payments.findByOrderId(orderId).getLast().status();
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.shipping.api.CarrierGateway;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/** A customer sends an order back. */
@Component
public class OrderReturns {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final Notifier notifier;
    private final CustomerFacade customers;

    public OrderReturns(OrderRepository orders, CarrierGateway carrier, Notifier notifier, CustomerFacade customers) {
        this.orders = orders;
        this.carrier = carrier;
        this.notifier = notifier;
        this.customers = customers;
    }

    @Transactional
    public String startReturn(String orderId) {
        Order order = orders.get(orderId);
        if ("CANCELLED".equals(order.status())) {
            throw new IllegalStateException("A cancelled order cannot be returned");
        }
        order.changeStatus("RETURNING");
        String label = carrier.book("return-" + orderId);
        notifier.send(customers.emailOf(order.customerId()), "Return " + orderId, "Your return label: " + label);
        return label;
    }
}

package com.wolinski.shop.orders.internal;

import java.util.Collection;
